-- Jerarquía: «Derivar Relaciones Jerárquicas en Redes Combinatorias» rehecho como la red Nurvani de
-- Villarroel y Luciano (tres niveles, dos ramas, una función por nodo): redes de cinco nodos y un
-- grupo de siete. Inclusión y distinción entre ramas (Sí/No), transformación de arriba abajo, de abajo
-- arriba («algunos, no todos»), sin mezclar ramas, y función dominante (opciones propias de cada clase).
begin;
delete from estimulos_rft_base where clase_base_id in (select id from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias'));
delete from clases_rft_base where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias');
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias'), 'Clase 1', 'Grupo 1', 1, $j${"entrenamiento:D→B": "El DES es un JAR. ¿Qué es el DES, un JAR o un ROB?", "entrenamiento:E→C": "El DUF es un ROB. ¿Qué es el DUF, un ROB o un JAR?", "entrenamiento:B→A": "Los JAR son NOF. ¿Qué son los JAR?", "entrenamiento:C→A": "Los ROB son NOF. ¿Qué son los ROB?", "test_mutuo:B→D": "El DES es un JAR. ¿Cuál de estos es un JAR?", "test_mutuo:C→E": "El DUF es un ROB. ¿Cuál de estos es un ROB?", "test_combinatorio:D→A": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. ¿Es el DES un NOF?", "test_combinatorio:D→C": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. ¿Es el DES un ROB?", "transformacion_funciones:A→D": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. Los NOF viven en las montañas. ¿Vive en las montañas el DES?", "transformacion_funciones:B→E": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. Los JAR son trabajadores. ¿Es trabajador el DUF?", "transformacion_funciones:D→A": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. El DES es gruñón. ¿Todos los NOF son gruñones?", "transformacion_funciones:D→E": "Los JAR y los ROB son NOF. El DES es un JAR y el DUF es un ROB. Los NOF viven en las montañas. Los JAR son trabajadores y los ROB, ruidosos. El DES es gruñón y el DUF, tranquilo. ¿Qué tienen en común el DES y el DUF?"}$j$::jsonb, $j${"test_combinatorio:D→A": "Sí", "test_combinatorio:D→C": "No", "transformacion_funciones:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "No", "transformacion_funciones:D→E": "Que viven en las montañas"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que son ruidosos", "Que viven en las montañas", "Que son gruñones", "Que son trabajadores"]}$j$::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, x.etiqueta, x.posicion, x.nombre, null from nueva, (values ('A1', 'A', 'Los NOF'), ('B1', 'B', 'Los JAR'), ('C1', 'C', 'Los ROB'), ('D1', 'D', 'El DES'), ('E1', 'E', 'El DUF')) x(etiqueta, posicion, nombre);
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias'), 'Clase 2', 'Grupo 1', 2, $j${"entrenamiento:D→B": "El DIK es un FIF. ¿Qué es el DIK, un FIF o un PUF?", "entrenamiento:E→C": "El ZAN es un PUF. ¿Qué es el ZAN, un PUF o un FIF?", "entrenamiento:B→A": "Los FIF son ZOF. ¿Qué son los FIF?", "entrenamiento:C→A": "Los PUF son ZOF. ¿Qué son los PUF?", "test_mutuo:B→D": "El DIK es un FIF. ¿Cuál de estos es un FIF?", "test_mutuo:C→E": "El ZAN es un PUF. ¿Cuál de estos es un PUF?", "test_combinatorio:D→A": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. ¿Es el DIK un ZOF?", "test_combinatorio:D→C": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. ¿Es el DIK un PUF?", "transformacion_funciones:A→D": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. Los ZOF comen solo fruta. ¿Come solo fruta el DIK?", "transformacion_funciones:B→E": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. Los FIF son pequeños. ¿Es pequeño el ZAN?", "transformacion_funciones:D→A": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. El DIK es curioso. ¿Alguno de los ZOF es curioso?", "transformacion_funciones:D→E": "Los FIF y los PUF son ZOF. El DIK es un FIF y el ZAN es un PUF. Los ZOF comen solo fruta. Los FIF son pequeños y los PUF, fuertes. El DIK es curioso y el ZAN, valiente. ¿Qué tienen en común el DIK y el ZAN?"}$j$::jsonb, $j${"test_combinatorio:D→A": "Sí", "test_combinatorio:D→C": "No", "transformacion_funciones:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "Sí", "transformacion_funciones:D→E": "Que comen solo fruta"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que son pequeños", "Que son curiosos", "Que comen solo fruta", "Que son fuertes"]}$j$::jsonb) returning id)
