with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias'), 'Clase 3', 'Grupo 1', 3, $j${"entrenamiento:D→B": "El SUB es un BUB. ¿Qué es el SUB, un BUB o un FEK?", "entrenamiento:E→C": "El SIR es un FEK. ¿Qué es el SIR, un FEK o un BUB?", "entrenamiento:B→A": "Los BUB son KOS. ¿Qué son los BUB?", "entrenamiento:C→A": "Los FEK son KOS. ¿Qué son los FEK?", "test_mutuo:B→D": "El SUB es un BUB. ¿Cuál de estos es un BUB?", "test_mutuo:C→E": "El SIR es un FEK. ¿Cuál de estos es un FEK?", "test_combinatorio:D→A": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. ¿Es el SUB un KOS?", "test_combinatorio:D→C": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. ¿Es el SUB un FEK?", "transformacion_funciones:A→D": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. Los KOS duermen de día. ¿Duerme de día el SUB?", "transformacion_funciones:B→E": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. Los BUB son constantes. ¿Es constante el SIR?", "transformacion_funciones:D→A": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. El SUB es amable. ¿Todos los KOS son amables?", "transformacion_funciones:D→E": "Los BUB y los FEK son KOS. El SUB es un BUB y el SIR es un FEK. Los KOS duermen de día. Los BUB son constantes y los FEK, perezosos. El SUB es amable y el SIR, alegre. ¿Qué tienen en común el SUB y el SIR?"}$j$::jsonb, $j${"test_combinatorio:D→A": "Sí", "test_combinatorio:D→C": "No", "transformacion_funciones:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "No", "transformacion_funciones:D→E": "Que duermen de día"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que son constantes", "Que son perezosos", "Que duermen de día", "Que son amables"]}$j$::jsonb) returning id)
