  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones Jerárquicas en Redes Combinatorias'), 'Clase 6', 'Grupo 2', 6, $j${"entrenamiento:D→B": "El MUR es un DEN. ¿Qué es el MUR, un DEN o un GIB?", "entrenamiento:E→C": "El SIS es un GIB. ¿Qué es el SIS, un GIB o un DEN?", "entrenamiento:B→A": "Los DEN son KUR. ¿Qué son los DEN?", "entrenamiento:C→A": "Los GIB son KUR. ¿Qué son los GIB?", "test_mutuo:B→D": "El MUR es un DEN. ¿Cuál de estos es un DEN?", "test_mutuo:C→E": "El SIS es un GIB. ¿Cuál de estos es un GIB?", "test_combinatorio:D→A": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. ¿Es el MUR un KUR?", "test_combinatorio:D→C": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. ¿Es el MUR un GIB?", "transformacion_funciones:A→D": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. Los KUR beben agua salada. ¿Bebe agua salada el MUR?", "transformacion_funciones:B→E": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. Los DEN son despistados. ¿Es despistado el SIS?", "transformacion_funciones:D→A": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. El MUR es alegre. ¿Alguno de los KUR es alegre?", "transformacion_funciones:D→E": "Los DEN y los GIB son KUR. El MUR es un DEN y el SIS es un GIB. Los KUR beben agua salada. Los DEN son despistados y los GIB, constantes. El MUR es alegre y el SIS, serio. ¿Qué tienen en común el MUR y el SIS?"}$j$::jsonb, $j${"test_combinatorio:D→A": "Sí", "test_combinatorio:D→C": "No", "transformacion_funciones:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "Sí", "transformacion_funciones:D→E": "Que beben agua salada"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que beben agua salada", "Que son despistados", "Que son alegres", "Que son constantes"]}$j$::jsonb) returning id)
