:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "No", "transformacion_funciones:D→E": "Que tienen cola"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que son despistados", "Que son alegres", "Que tienen cola", "Que son pequeños"]}$j$::jsonb) returning id)
