: "No", "transformacion_funciones:A→D": "Sí", "transformacion_funciones:B→E": "No", "transformacion_funciones:D→A": "Sí", "transformacion_funciones:D→E": "Que cantan al amanecer"}$j$::jsonb, $j${"transformacion_funciones:D→E": ["Que son agresivos", "Que son ordenados", "Que cantan al amanecer", "Que son despistados"]}$j$::jsonb) returning id)
